public class CursorTokenProbe {
    public static Map<String,Object> inspect(String payload) {
        Map<String,Object> answer=new Map<String,Object>{
            'admitted'=>false, 'value'=>null, 'serialized'=>null,
            'exceptionType'=>null, 'exceptionMessage'=>null
        };
        try {
            Database.Cursor handle=(Database.Cursor)JSON.deserialize(payload,Database.Cursor.class);
            answer.put('admitted',true);
            answer.put('value',handle==null?'null':'nonnull');
            answer.put('serialized',JSON.serialize(handle));
        } catch (Exception issue) {
            answer.put('exceptionType',issue.getTypeName());
            answer.put('exceptionMessage',issue.getMessage());
        }
        return answer;
    }

    public static Map<String,Object> observe(Database.Cursor original, Account seed) {
        Map<String,Object> result=new Map<String,Object>();
        String originalJSON=JSON.serialize(original);
        Map<String,Object> originalData=(Map<String,Object>)JSON.deserializeUntyped(originalJSON);
        String originalToken=(String)originalData.get('queryId');
        result.put('malformed',inspect(JSON.serialize(new Map<String,Object>{'queryId'=>'UnusableCursor67890'})));
        result.put('renewed',inspect(JSON.serialize(new Map<String,Object>{'queryId'=>originalToken+'-renewed'})));
        result.put('empty',inspect('{}'));
        result.put('null',inspect('null'));
        Map<String,Object> roundtrip=new Map<String,Object>{
            'admitted'=>false, 'count'=>null, 'fetched'=>null, 'sameId'=>null, 'sameName'=>null,
            'exceptionType'=>null, 'exceptionMessage'=>null
        };
        try {
            Database.Cursor restored=(Database.Cursor)JSON.deserialize(originalJSON,Database.Cursor.class);
            roundtrip.put('admitted',restored!=null);
            roundtrip.put('count',restored.getNumRecords());
            List<SObject> rows=restored.fetch(0,1);
            roundtrip.put('fetched',rows.size());
            roundtrip.put('sameId',rows.isEmpty()?false:rows[0].Id==seed.Id);
            roundtrip.put('sameName',rows.isEmpty()?false:rows[0].get('Name')==seed.Name);
        } catch (Exception issue) {
            roundtrip.put('exceptionType',issue.getTypeName());
            roundtrip.put('exceptionMessage',issue.getMessage());
        }
        result.put('roundtrip',roundtrip);
        return result;
    }
}

